window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-936a6b730a48bdc1"]={"versions": [{"id": "FIG-936a6b730a48bdc1", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform Timing Extensions (Subpaket <code>EventTriggeringConstraint</code>). Dargestellt ist das Metamodell für periodische Ereignisauslösungen (<code>PeriodicEventTriggering</code>) und deren zeitliche Bemessung über <code>MultidimensionalTime</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert zwei Metaklassen:</p>\n<ul class=\"fig-list\">\n<li><code>EventTriggeringConstraint::PeriodicEventTriggering</code> (im Paket bzw. Kontext <code>EventTriggeringConstraint</code>): Repräsentiert die periodische Triggerbedingung. Sie besitzt drei Kompositionen zu <code>MultidimensionalTime::MultidimensionalTime</code>:</li>\n<li><code>+period</code>: Kardinalität <code>1</code></li>\n<li><code>+jitter</code>: Kardinalität <code>1</code></li>\n<li><code>+minimumInterArrivalTime</code>: Kardinalität <code>1</code></li>\n<li><code>MultidimensionalTime::MultidimensionalTime</code> (im Paket <code>MultidimensionalTime</code>): Hält zeitliche Dimensionierungsdaten mit den Attributen:</li>\n<li><code>+cseCode: CseCodeType</code> (Kardinalität 1)</li>\n<li><code>+cseCodeFactor: Integer</code> (Kardinalität 1)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablaufsequenz. Die Instanzen definieren zur Laufzeit bzw. Konfigurationszeit das Ankunftsverhalten von Events: Eine Periode (<code>period</code>), eine zulässige zeitliche Schwankung (<code>jitter</code>) sowie eine minimale Zeit zwischen aufeinanderfolgenden Ereignissen (<code>minimumInterArrivalTime</code>), jeweils dimensioniert durch ein eigenes <code>MultidimensionalTime</code>-Objekt mit Skalierungsfaktor und Code.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Metamodell für Timing-Beschreibungen periodischer Ereignisse. In dieser Fassung sind alle drei Zeiteigenschaften (<code>period</code>, <code>jitter</code>, <code>minimumInterArrivalTime</code>) verpflichtend mit Kardinalität <code>1</code> zu instanziieren. Ebenso müssen <code>cseCode</code> und <code>cseCodeFactor</code> in jedem <code>MultidimensionalTime</code>-Element vorhanden sein.</p>"}, {"id": "FIG-1c48fc0d30b89904", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform Timing Extensions (Subpaket <code>EventTriggeringConstraint</code>). Dargestellt ist das Metamodell für periodische Ereignisauslösungen (<code>PeriodicEventTriggering</code>) und deren zeitliche Bemessung über <code>MultidimensionalTime</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert zwei Metaklassen:</p>\n<ul class=\"fig-list\">\n<li><code>PeriodicEventTriggering</code> (im Kontext <code>EventTriggeringConstraint</code>): Repräsentiert die periodische Triggerbedingung. Sie besitzt drei Kompositionen zu <code>MultidimensionalTime</code>:</li>\n<li><code>+period</code>: Kardinalität <code>1</code></li>\n<li><code>+jitter</code>: Kardinalität <code>1</code></li>\n<li><code>+minimumInterArrivalTime</code>: Kardinalität <code>1</code></li>\n<li><code>MultidimensionalTime</code>: Hält zeitliche Dimensionierungsdaten mit den Attributen:</li>\n<li><code>+cseCode: CseCodeType</code> (Kardinalität 1)</li>\n<li><code>+cseCodeFactor: Integer</code> (Kardinalität 1)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablaufsequenz. Die Instanzen definieren zur Laufzeit bzw. Konfigurationszeit das Ankunftsverhalten von Events: Eine Periode (<code>period</code>), eine zulässige zeitliche Schwankung (<code>jitter</code>) sowie eine minimale Zeit zwischen aufeinanderfolgenden Ereignissen (<code>minimumInterArrivalTime</code>), jeweils dimensioniert durch ein eigenes <code>MultidimensionalTime</code>-Objekt mit Skalierungsfaktor und Code.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Metamodell für Timing-Beschreibungen periodischer Ereignisse. In dieser Fassung sind alle drei Zeiteigenschaften (<code>period</code>, <code>jitter</code>, <code>minimumInterArrivalTime</code>) verpflichtend mit Kardinalität <code>1</code> zu instanziieren. Ebenso müssen <code>cseCode</code> und <code>cseCodeFactor</code> in jedem <code>MultidimensionalTime</code>-Element vorhanden sein.</p>"}, {"id": "FIG-a4a29d48f4ffde7c", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Adaptive Platform Timing Extensions (Subpaket <code>EventTriggeringConstraint</code>). Dargestellt ist das Metamodell für periodische Ereignisauslösungen (<code>PeriodicEventTriggering</code>) und deren zeitliche Bemessung über <code>MultidimensionalTime</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert zwei Metaklassen:</p>\n<ul class=\"fig-list\">\n<li><code>PeriodicEventTriggering</code> (im Kontext <code>EventTriggeringConstraint</code>): Repräsentiert die periodische Triggerbedingung. Sie besitzt drei Kompositionen zu <code>MultidimensionalTime</code>:</li>\n<li><code>+period</code>: Kardinalität <code>0..1</code></li>\n<li><code>+jitter</code>: Kardinalität <code>0..1</code></li>\n<li><code>+minimumInterArrivalTime</code>: Kardinalität <code>0..1</code></li>\n<li><code>MultidimensionalTime</code>: Hält zeitliche Dimensionierungsdaten mit den Attributen:</li>\n<li><code>+cseCode: CseCodeType [0..1]</code></li>\n<li><code>+cseCodeFactor: Integer [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablaufsequenz. Die Instanzen definieren das Ankunftsverhalten von Events. Periode (<code>period</code>), Jitter (<code>jitter</code>) sowie minimale Ankunftsabstände (<code>minimumInterArrivalTime</code>) können jeweils optional definiert und über <code>MultidimensionalTime</code> mit Code und Faktor parametrisiert werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliches Metamodell für Timing-Beschreibungen periodischer Ereignisse. Die zeitlichen Attribute (<code>period</code>, <code>jitter</code>, <code>minimumInterArrivalTime</code>) sowie die Attribute <code>cseCode</code> und <code>cseCodeFactor</code> besitzen jeweils die Kardinalität <code>0..1</code>. Modelle können daher einzelne Zeitparameter weglassen, und Parser/Generatoren müssen das Fehlen dieser Rollen und Attribute fehlerfrei handhaben.</p>"}], "trans": [{"from": "FIG-936a6b730a48bdc1", "to": "FIG-1c48fc0d30b89904", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Klassennamen: Qualifizierende Package-Präfixe <code>EventTriggeringConstraint::</code> vor <code>PeriodicEventTriggering</code> sowie <code>MultidimensionalTime::</code> vor <code>MultidimensionalTime</code> entfernt.</li>\n<li>Rollenbezeichner: Reihenfolge der Assoziationsbeschriftungen von <code>+minimumInterArrivalTime 1 +jitter 1 +period 1</code> vereinheitlicht zu <code>+period 1 +jitter 1 +minimumInterArrivalTime 1</code>.</li>\n</ul>"}, {"from": "FIG-1c48fc0d30b89904", "to": "FIG-a4a29d48f4ffde7c", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kardinalität: Assoziationsenden <code>period</code>, <code>jitter</code> und <code>minimumInterArrivalTime</code> von <code>1</code> auf <code>0..1</code> geändert (Optionalität von Zeitparametern).</li>\n<li>Kardinalität / Attribute: Multiplizität der Attribute <code>cseCode</code> und <code>cseCodeFactor</code> in <code>MultidimensionalTime</code> explizit von implizit <code>1</code> auf <code>[0..1]</code> geändert.</li>\n</ul>"}]};
